function shoppingFixture(){const f=fixture();vm.runInContext(fs.readFileSync('google-spinner/ServiceShopping.js','utf8'),f.ctx);f.ctx.purchasingActor_=session=>({email:session.email,name:'Director',periods:['2'],admin:false,manager:false});const transfers=[];f.ctx.purchasingBudgetRequest_=(token,actor,operation,payload)=>{transfers.push(structuredClone({token,actor,operation,payload}));return {status:200,saved:true};};return {...f,transfers};}
const shoppingId='44444444-4444-4444-8444-444444444444';
