const shoppingItem={itemId:shoppingId,title:'Chair caster',quantity:4,unitCost:5.25,url:'https://supplier.example/caster',notes:'For chair repair',fund:'CTE'};
test('ticket shopping list enforces ticket edit permission and versions, journals changes and exports no client contacts',()=>{const {ctx,state,transfers}=shoppingFixture();assert.equal(shoppingChange(ctx,'save',shoppingItem,'outsider').status,403);assert.equal(shoppingChange(ctx,'save',shoppingItem).status,200);const row=ctx.serviceRead_().requests.find(x=>x.id===first);assert.equal(ctx.serviceShoppingRead_(row,ctx.serviceRead_().events).items[0].quantity,4);assert.equal(ctx.serviceDispatch_({action:'auth-service-shopping-save',session:'director',id:first,version:'stale',...shoppingItem}).status,409);assert.equal(shoppingChange(ctx,'push').status,200);assert.equal(transfers.length,1);assert.equal(transfers[0].operation,'service-import');assert.equal(transfers[0].payload.items[0].id,shoppingId);assert.equal(transfers[0].payload.items[0].division,'2');assert.equal(JSON.stringify(transfers[0]).includes('staff@'),false);assert.equal(shoppingChange(ctx,'push').status,200);assert.equal(transfers.length,1);assert.equal(shoppingChange(ctx,'save',{...shoppingItem,title:'Updated caster',quantity:6}).status,200);assert.equal(transfers.at(-1).operation,'service-change');const projected=ctx.serviceShoppingInventory_({email:'owner@bethelsd.org'},{manager:true});assert.equal(projected.tickets.length,1);assert.equal(JSON.stringify(projected).includes('SECRET'),false);assert.equal(JSON.stringify(projected).includes('555-1234'),false);assert.equal(shoppingChange(ctx,'remove',{itemId:shoppingId}).status,200);assert.equal(ctx.serviceShoppingInventory_({email:'owner@bethelsd.org'},{manager:true}).tickets.length,0);assert.equal(state.mail.length,0);});
test('an uncertain shopping transfer freezes exact lines and retries the same IDs without permitting edits',()=>{const {ctx,transfers}=shoppingFixture();assert.equal(shoppingChange(ctx,'save',shoppingItem).status,200);const original=ctx.purchasingBudgetRequest_;ctx.purchasingBudgetRequest_=()=>{throw Error('timeout');};assert.equal(shoppingChange(ctx,'push').status,503);let state=ctx.serviceRead_(),item=state.requests.find(x=>x.id===first);assert.equal(ctx.serviceShoppingRead_(item,state.events).items[0].transferState,'pending');assert.equal(shoppingChange(ctx,'save',{...shoppingItem,quantity:100}).status,409);ctx.purchasingBudgetRequest_=original;assert.equal(shoppingChange(ctx,'push').status,200);assert.equal(transfers.length,1);assert.equal(transfers[0].payload.items[0].quantity,4);assert.equal(transfers[0].payload.items[0].id,shoppingId);state=ctx.serviceRead_();item=state.requests.find(x=>x.id===first);const list=ctx.serviceShoppingRead_(item,state.events);assert.ok(list.items[0].sentAt);assert.equal(list.history.length,4);});
