test('HTTP shopping operations forward fixed item fields and reject forged values before reaching the school gateway',async()=>{const old=globalThis.fetch;process.env.SPINNER_BRIDGE_URL='https://script.google.com/test';process.env.SPINNER_BRIDGE_TOKEN='test';let sent;globalThis.fetch=async(_url,opts)=>{sent=JSON.parse(opts.body);return {ok:true,json:async()=>({status:200,request:{id:first,version:'c'.repeat(64)}})};};const headers={origin:'https://gknest.org','content-type':'application/json',cookie:'__Host-nest-auth='+'a'.repeat(64)};try{let res=response();await handler({method:'POST',headers,body:{operation:'shopping-save',id:first,version:'b'.repeat(64),...shoppingItem,actor:{admin:true},division:'5',sentAt:'forged'}},res);assert.equal(res.code,200);assert.equal(sent.action,'auth-service-shopping-save');assert.equal(sent.quantity,4);for(const key of ['actor','division','sentAt'])assert.equal(key in sent,false);res=response();await handler({method:'POST',headers,body:{operation:'shopping-save',id:first,version:'b'.repeat(64),...shoppingItem,quantity:-1}},res);assert.equal(res.code,400);res=response();await handler({method:'POST',headers,body:{operation:'shopping-push',id:first,version:'b'.repeat(64),items:[{admin:true}]}},res);assert.equal(res.code,200);assert.equal('items' in sent,false);}finally{globalThis.fetch=old;delete process.env.SPINNER_BRIDGE_URL;delete process.env.SPINNER_BRIDGE_TOKEN;}});
