test('assigned team members can correct ticket details; phone normalization is consistent and stale/outsider writes are denied',()=>{const f=workspaceFixture(),fields={phone:'1-253-800-6221 ext 342',room:'Library',category:'Fabrication',urgency:'3',description:'Updated chair repair details'};assert.equal(workspaceChange(f,'details',{fields},'outsider').status,403);const old=f.ctx.serviceRead_().requests[0].version;assert.equal(workspaceChange(f,'details',{fields}).status,200);let row=f.ctx.serviceRead_().requests.find(x=>x.id===first);assert.equal(row.phone,'(253) 800-6221 x342');assert.equal(row.description,fields.description);assert.equal(row.email,'staff@bethelsd.org');assert.equal(f.ctx.serviceDispatch_({action:'auth-service-details',session:'director',id:first,version:old,fields}).status,409);assert.equal(f.state.mail.length,0);});
test('additional verified clients gain client-safe access and removal revokes it without changing the submitter or emailing',()=>{const f=workspaceFixture(),outside='outside@example.com';assert.equal(workspaceChange(f,'clients',{clients:[{name:'Outside client',email:outside,address:'Example address'}]}).status,200);const session=clientSession(f,outside);let view=f.ctx.serviceDispatch_({action:'service-client-view',session});assert.equal(view.requests.length,1);assert.equal(view.requests[0].canAct,true);assert.equal(JSON.stringify(view).includes('SECRET'),false);assert.equal(workspaceChange(f,'clients',{clients:[]}).status,200);assert.equal(f.ctx.serviceDispatch_({action:'service-client-view',session}).requests.length,0);assert.equal(f.state.mail.length,0);});
test('published shopping lists support questions, team responses, table and client purchase, with stable-ID retry and no fiscal email',()=>{const f=workspaceFixture();shoppingChange(f.ctx,'save',shoppingItem);shoppingChange(f.ctx,'push');assert.equal(clientShoppingAction(f,'question',shoppingId,'Which size?').status,403);assert.equal(workspaceChange(f,'shopping-publish',{visible:true}).status,200);assert.equal(clientShoppingAction(f,'question',shoppingId,'Which size?').status,200);let state=f.ctx.serviceRead_(),ticket=state.requests.find(x=>x.id===first),line=f.ctx.serviceShoppingRead_(ticket,state.events).items[0];assert.equal(line.followUp,true);assert.equal(line.questions[0].text,'Which size?');assert.equal(workspaceChange(f,'shopping-reply',{itemId:shoppingId,actionId:'88888888-8888-4888-8888-888888888888',text:'Use the 2-inch caster.'}).status,200);state=f.ctx.serviceRead_();ticket=state.requests.find(x=>x.id===first);line=f.ctx.serviceShoppingRead_(ticket,state.events).items[0];assert.equal(line.followUp,false);assert.equal(line.questions.at(-1).kind,'answer');assert.equal(clientShoppingAction(f,'table').status,200);const actionId='99999999-9999-4999-8999-999999999999';assert.equal(clientShoppingAction(f,'purchased',shoppingId,'',{actionId}).status,200);const repeat=clientShoppingAction(f,'purchased',shoppingId,'',{actionId});assert.equal(repeat.status,200);state=f.ctx.serviceRead_();ticket=state.requests.find(x=>x.id===first);line=f.ctx.serviceShoppingRead_(ticket,state.events).items[0];assert.equal(line.clientStatus,'purchased');assert.ok(line.purchasedAt);assert.equal(f.state.mail.length,0);assert.equal(f.transfers.at(-1).operation,'service-client-action');});
test('Inventory sharing toggles retain the service list, withdraw its Inventory projection and restore it',()=>{const f=workspaceFixture();shoppingChange(f.ctx,'save',shoppingItem);shoppingChange(f.ctx,'push');assert.equal(workspaceChange(f,'shopping-visibility',{visible:false}).status,200);let state=f.ctx.serviceRead_(),ticket=state.requests.find(x=>x.id===first);assert.equal(f.ctx.serviceShoppingRead_(ticket,state.events).items.length,1);assert.equal(f.ctx.serviceShoppingInventory_({email:'director@students.bethelsd.org'},{manager:true}).tickets.length,0);assert.equal(shoppingChange(f.ctx,'push').status,409);assert.equal(workspaceChange(f,'shopping-visibility',{visible:true}).status,200);assert.equal(f.ctx.serviceShoppingInventory_({email:'director@students.bethelsd.org'},{manager:true}).tickets.length,1);assert.equal(f.transfers.at(-1).operation,'service-visibility');});
test('internal and client-facing log media have independent ownership and client visibility, and log retry cannot duplicate an entry',()=>{const f=workspaceFixture(),entryId='88888888-8888-4888-8888-888888888888',fileId='99999999-9999-4999-8999-999999999999',email='director@students.bethelsd.org',file={ticketId:first,fileId,name:'Private repair.jpg',size:3,type:'image/jpeg',path:'service-media/'+first+'/'+fileId+'.jpg',context:'internal',entryId,complete:true};f.store.setProperty('service-work:files:'+first+':'+hash(email),JSON.stringify({email,files:[file],expires:Date.now()+60000}));let row=f.ctx.serviceRead_().requests.find(x=>x.id===first);const request={action:'auth-service-update',session:'director',id:first,version:row.version,status:row.status,manager:row.manager,note:'Private repair observation',publicNote:'',entryId,attachmentIds:[fileId]};const saved=f.ctx.serviceDispatch_(request);assert.equal(saved.status,200);assert.equal(saved.request.internalUpdates.at(-1).attachments.length,1);assert.equal(f.ctx.serviceDispatch_(request).status,200);assert.equal(f.ctx.serviceRead_().events.filter(e=>e[2]==='update'&&e[6]===entryId).length,1);const client=clientSession(f,'staff@bethelsd.org');assert.equal(f.ctx.serviceDispatch_({action:'auth-service-attachment-read',clientSession:client,ticketId:first,fileId}).status,403);assert.equal(f.ctx.serviceDispatch_({action:'auth-service-attachment-read',session:'director',ticketId:first,fileId}).status,200);row=f.ctx.serviceRead_().requests.find(x=>x.id===first);const message=f.ctx.serviceEmailMessage_(row,f.ctx.serviceRead_().events,'entire',f.ctx.serviceRoster_(),true);assert.equal(message.htmlBody.includes('Private repair.jpg'),false);assert.equal(message.htmlBody.includes('Private repair observation'),false);});
test('selected client media appears as secure email links; every additional client is an explicit recipient',()=>{const f=workspaceFixture();workspaceChange(f,'clients',{clients:[{name:'Outside client',email:'outside@example.com'}]});const file={ticketId:first,fileId:'99999999-9999-4999-8999-999999999999',name:'Visible photo.jpg',size:3,type:'image/jpeg'};f.state.grids.ServiceWebLog.push(['2026-11-03',first,'attachments','director','Assigned','Files','77777777-7777-4777-8777-777777777777','','',JSON.stringify([file])]);let row=f.ctx.serviceRead_().requests.find(x=>x.id===first);const updated=f.ctx.serviceWrite_('director@students.bethelsd.org',{action:'auth-service-update',id:first,version:row.version,status:row.status,manager:row.manager,note:'PRIVATE',publicNote:'Please review the photo.'});assert.equal(updated.status,200);row=f.ctx.serviceRead_().requests.find(x=>x.id===first);let message=f.ctx.serviceEmailMessage_(row,f.ctx.serviceRead_().events,'latest',f.ctx.serviceRoster_(),true);assert.match(message.htmlBody,/Photos and videos/);assert.match(message.htmlBody,/Visible photo.jpg/);assert.equal(f.ctx.serviceEmailMessage_(row,f.ctx.serviceRead_().events,'latest',f.ctx.serviceRoster_(),false).htmlBody.includes('Visible photo.jpg'),false);const result=f.ctx.serviceDispatch_({action:'auth-service-email',session:'director',id:first,version:row.version,eventId:updated.eventId,includeMedia:true,logMode:'latest',cc:[]});assert.equal(result.status,200);assert.equal(f.state.mail[0].to,'staff@bethelsd.org,outside@example.com');assert.equal(f.state.mail[0].htmlBody.includes('PRIVATE'),false);});

function driveFixture(){const f=workspaceFixture(),files=new Map(),permissions=new Map(),removed=[],requests=[];let n=0;f.ctx.ScriptApp={getOAuthToken:()=> 'fake-test-token-not-a-real-credential'};f.ctx.Drive={Files:{create(meta){const id='drive_file_'+String(++n).padStart(8,'0');files.set(id,{...structuredClone(meta),id,size:0});return {id,webViewLink:'https://drive.google.com/file/d/'+id+'/view'};},get(id){return files.get(id);}},Permissions:{list(id){return {permissions:[{id:'owner',emailAddress:'owner@bethelsd.org',role:'owner'},...(permissions.get(id)||[])]};},create(meta,id,opts){assert.equal(opts.sendNotificationEmail,false);const permission={...meta,id:'permission-'+(++n),emailAddress:meta.emailAddress};permissions.set(id,[...(permissions.get(id)||[]),permission]);return permission;},remove(id,pid){removed.push({id,pid});permissions.set(id,(permissions.get(id)||[]).filter(x=>x.id!==pid));}}};f.ctx.UrlFetchApp={fetch(url,opts){requests.push({url,...opts});return {getResponseCode:()=>200,getAllHeaders:()=>({Location:'https://www.googleapis.com/upload/drive/v3/files/session-test'})};}};vm.runInContext(fs.readFileSync('google-spinner/ServiceDrive.js','utf8'),f.ctx);return {...f,files,permissions,removed,requests};}
test('Drive ticket folders are idempotent, share client media by link and keep internal media separate',()=>{const f=driveFixture();let state=f.ctx.serviceRead_(),ticket=state.requests.find(x=>x.id===first);const info=f.ctx.serviceDriveSync_(ticket,state.events),again=f.ctx.serviceDriveSync_(ticket,state.events);assert.equal(info.url,again.url);assert.equal(f.files.size,3);const folder=f.ctx.serviceDriveFolders_(first),pub=f.files.get(folder.publicId),internal=f.files.get(folder.internalId);assert.equal(pub.parents[0],internal.parents[0]);assert.notEqual(pub.parents[0],folder.publicId);assert.equal(pub.writersCanShare,false);assert.equal((f.permissions.get(folder.publicId)||[]).some(p=>p.type==='anyone'&&p.role==='reader'&&p.allowFileDiscovery===false),true);assert.equal((f.permissions.get(folder.internalId)||[]).some(p=>p.emailAddress==='staff@bethelsd.org'),false);assert.equal((f.permissions.get(folder.internalId)||[]).some(p=>p.emailAddress==='student@students.bethelsd.org'&&p.role==='writer'),true);assert.equal(f.state.mail.length,0);});
test('Drive upload grants expose only a scoped upload session and validate completed file size/type before accepting it',()=>{const f=driveFixture(),file={ticketId:first,fileId:'99999999-9999-4999-8999-999999999999',name:'Repair photo.jpg',size:3,type:'image/jpeg',context:'ticket'},grant={email:'director@students.bethelsd.org',files:[],expires:Date.now()+60000};const prepared=f.ctx.serviceDrivePrepare_(file,grant,'grant',f.store);assert.equal(prepared.status,200);assert.equal(prepared.file.storage,'drive');assert.equal('readToken' in prepared,false);assert.equal('uploadUrl' in prepared.file,false);assert.match(prepared.uploadUrl,/googleapis.com\/upload\/drive/);assert.equal(f.ctx.serviceDriveComplete_(prepared.file,grant,'grant',f.store).status,404);f.files.get(prepared.file.driveId).size=3;assert.equal(f.ctx.serviceDriveComplete_(prepared.file,grant,'grant',f.store).status,200);assert.equal(f.ctx.serviceDrivePrepare_(file,grant,'grant',f.store).complete,true);assert.equal(f.requests.length,1);assert.equal(grant.files[0].uploadUrl,undefined);});
test('removing an additional client revokes ticket access while internal Drive folders stay private',()=>{const f=driveFixture();workspaceChange(f,'clients',{clients:[{name:'Outside',email:'outside@example.com'}]});const folder=f.ctx.serviceDriveFolders_(first);assert.equal((f.permissions.get(folder.publicId)||[]).some(p=>p.type==='anyone'&&p.role==='reader'),true);assert.equal((f.permissions.get(folder.internalId)||[]).some(p=>p.emailAddress==='outside@example.com'),false);workspaceChange(f,'clients',{clients:[]});assert.equal((f.permissions.get(folder.publicId)||[]).some(p=>p.emailAddress==='outside@example.com'),false);assert.equal((f.permissions.get(folder.internalId)||[]).some(p=>p.type==='anyone'),false);});

test('email checkboxes include an inventory-only list explicitly without publishing it, exclude private fields, and isolate duplicate send states',()=>{const f=workspaceFixture();shoppingChange(f.ctx,'save',{...shoppingItem,notes:'INTERNAL PROCUREMENT NOTE'});let state=f.ctx.serviceRead_(),row=state.requests.find(x=>x.id===first);const updated=f.ctx.serviceWrite_('director@students.bethelsd.org',{action:'auth-service-update',id:first,version:row.version,status:row.status,manager:row.manager,note:'PRIVATE INTERNAL LOG',publicNote:'Please review the project list.'});state=f.ctx.serviceRead_();row=state.requests.find(x=>x.id===first);assert.equal(f.ctx.serviceClientShopping_(row,state.events).available,false);assert.equal(f.ctx.serviceEmailMessage_(row,state.events,'latest',f.ctx.serviceRoster_(),false,false).htmlBody.includes('Chair caster'),false);const message=f.ctx.serviceEmailMessage_(row,state.events,'latest',f.ctx.serviceRoster_(),false,true);assert.match(message.htmlBody,/Chair caster/);assert.match(message.htmlBody,/Purchase responsibility not yet confirmed/);assert.equal(message.htmlBody.includes('INTERNAL PROCUREMENT NOTE'),false);assert.equal(message.htmlBody.includes('PRIVATE INTERNAL LOG'),false);const request={action:'auth-service-email',session:'director',id:first,version:row.version,eventId:updated.eventId,includeMedia:false,includeShopping:true,logMode:'latest',cc:[]};const sent=f.ctx.serviceDispatch_(request);assert.equal(sent.status,200);assert.equal(f.state.mail.length,1);assert.equal(sent.request.emailOptionStates['01'].latest,'sent');assert.equal(sent.request.emailOptionStates['00'].latest,'unsent');assert.equal(f.ctx.serviceClientShopping_(f.ctx.serviceRead_().requests.find(x=>x.id===first),f.ctx.serviceRead_().events).available,false);assert.equal(f.ctx.serviceDispatch_({...request,version:sent.request.version}).status,409);assert.equal(f.state.mail.length,1);});
